+    let (start_row, end_row) = selected_row_range(selection, lines);
+    let start_column = selection.anchor.column.min(selection.cursor.column);
+    let end_column = selection.anchor.column.max(selection.cursor.column) + 1;
+    lines[start_row..=end_row]
+        .iter()
+        .map(|line| {
+            let line_len = line.chars().count();
+            if start_column >= line_len {
+                String::new()
+            } else {
+                slice_chars(line, start_column, end_column.min(line_len))
+            }
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selected_character_text(selection: VisualSelection, lines: &[String]) -> String {
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    let (start_row, end_row) = selected_row_range(selection, lines);
+    (start_row..=end_row)
+        .map(|row| {
+            let line = &lines[row];
+            let line_len = line.chars().count();
+            if start_row == end_row {
+                let start_column = start.column.min(line_len);
+                let end_column = (end.column + 1).min(line_len);
+                slice_chars(line, start_column, end_column)
+            } else if row == start_row {
+                let start_column = start.column.min(line_len);
+                slice_chars(line, start_column, line_len)
+            } else if row == end_row {
+                let end_column = (end.column + 1).min(line_len);
+                slice_chars(line, 0, end_column)
+            } else {
+                line.clone()
+            }
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn max_selectable_column(lines: &[String]) -> usize {
+    lines
+        .iter()
+        .map(|line| line.chars().count().saturating_sub(1))
+        .max()
+        .unwrap_or(0)
+}
+
+fn slice_chars(text: &str, start: usize, end: usize) -> String {
+    text.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn osc52_copy_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const ALPHABET: &[u8; 64] =
+        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::with_capacity(bytes.len().div_ceil(3) * 4);
+    for chunk in bytes.chunks(3) {
+        let first = chunk[0];
+        let second = chunk.get(1).copied().unwrap_or(0);
+        let third = chunk.get(2).copied().unwrap_or(0);
+
+        encoded.push(ALPHABET[usize::from(first >> 2)] as char);
+        encoded.push(ALPHABET[usize::from(((first & 0b0000_0011) << 4) | (second >> 4))] as char);
+        if chunk.len() > 1 {
+            encoded
+                .push(ALPHABET[usize::from(((second & 0b0000_1111) << 2) | (third >> 6))] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(ALPHABET[usize::from(third & 0b0011_1111)] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}
